--
-- Table structure for table `event_volunteer`
--

DROP TABLE IF EXISTS `event_volunteer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_volunteer` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `event_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `joined_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('confirmed','completed','absent') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'confirmed',
  `attendance_status` enum('confirmed','pending_review','completed','absent') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'confirmed',
  `absence_reason` text COLLATE utf8mb4_unicode_ci,
  `points_awarded` tinyint(1) NOT NULL DEFAULT '0',
  `points_earned` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `event_volunteer_event_id_user_id_unique` (`event_id`,`user_id`),
  KEY `event_volunteer_user_id_foreign` (`user_id`),
  CONSTRAINT `event_volunteer_event_id_foreign` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE,
  CONSTRAINT `event_volunteer_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6665 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

